# Let me implement: cell (r,c) becomes 3 if there exists an original (r0,c0) such that:
# c - c0 = (r - r0) / 2  OR  c - c0 = -(r - r0) / 2
# That is, the point is on one of two lines with slope ±0.5 from each original

orig_3s = [(5,5), (6,3), (6,4), (7,3), (7,4), (8,3)]

def is_diagonal_band(r, c, orig_cells):
    for r0, c0 in orig_cells:
        # Check two possible relationships
        # c - c0 = k * (r - r0) for some slope k
        dr = r - r0
        dc = c - c0
        if dr == 0:
            continue
        # Check if dc/dr ≈ 0.5 or ≈ -0.5
        ratio = dc / dr
        # Due to rounding, check both 0.5 and -0.5
        if abs(ratio - 0.5) < 0.01 or abs(ratio + 0.5) < 0.01:
            return True
    return False

demoout_r3_set = {(r,c): True for r in range(21) for c in range(13) if demoout[r][c] == 3}

# Test the formula
correct = 0
incorrect = 0
for r in range(21):
    for c in range(13):
        is_3_actual = (r,c) in demoout_r3
        is_3_predicted = is_diagonal_band(r, c, orig_3s)
        if is_3_actual != is_3_predicted:
            if is_3_actual and not is_3_predicted:
                incorrect += 1
                if incorrect <= 3:
                    print(f"Missed (in actual, out predicted): {r},{c}, dr={r-orig_3s[3][0]}, dc={c-orig_3s[3][1]}")
            elif not is_3_actual and is_3_predicted:
                incorrect += 1
                if incorrect <= 3:
                    print(f"Extra (out actual, in predicted): {r},{c}, dr={r-orig_3s[3][0]}, dc={c-orig_3s[3][1]}")

print(f"Total incorrect: {incorrect}")

